#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD1 = 998244353;
const ll MOD2 = 1000000007;
const int MAX_S = 7;
const int PRE_SIZE = 1111110;

vector<ll> seq[MAX_S];
ll prefix[MAX_S];
ll NTH_VAL;

inline ll diff_mod(ll a, ll b) {
    return ((a - b) % MOD1 + MOD1) % MOD1;
}

ll next_val(ll cur, ll limit) {
    if (cur * 10 <= limit) return cur * 10;
    cur++;
    if (cur <= limit) {
        while (cur % 10 == 0) cur /= 10;
    } else {
        cur = (cur - 1) / 10 + 1;
        while (cur % 10 == 0) cur /= 10;
    }
    return cur;
}

int len_arr[1000010];

void preprocess() {
    ll cur_val = 0, cur_len = 1;
    ll idx = 1;
    for (int i = 0; i < PRE_SIZE; ++i) {
        seq[cur_len].push_back(diff_mod(idx, cur_val));
        idx++;
        if (cur_len < 6) {
            cur_len++;
            cur_val *= 10;
        } else {
            cur_val++;
            while (cur_val % 10 == 0) cur_val /= 10;
            cur_len--;
        }
    }

    for (int l = 1; l < MAX_S; ++l) {
        sort(seq[l].begin(), seq[l].end());
        for (ll x : seq[l]) {
            prefix[l] = (prefix[l] + x) % MOD2;
        }
    }

    int edge = 1, f = 0;
    for (int i = 1; i <= 1000000; ++i) {
        if (i == edge) {
            edge *= 10;
            f++;
        }
        len_arr[i] = f;
    }
}

ll compute_segment(ll start_val, ll start_idx, ll limit) {
    ll res = 0;
    ll st_val = start_val / 100;
    st_val++;
    while (st_val % 10 == 0) st_val /= 10;
    while (start_val != st_val) {
        res = (res + diff_mod(start_idx, start_val)) % MOD2;
        start_idx++;
        start_val = next_val(start_val, limit);
    }
    NTH_VAL = start_idx;
    return res;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    preprocess();

    ll n;
    cin >> n;

    if (n < 10000000) {
        ll ans = 0, val = 1;
        for (ll i = 1; i <= n; ++i) {
            ans = (ans + diff_mod(i, val)) % MOD2;
            if (i == n) break;
            val = next_val(val, n);
        }
        cout << ans << '\n';
        return 0;
    }

    ll ans = 0, val = 1, idx = 1;
    ll block_limit = n / 1000000;

    while (true) {
        ans = (ans + diff_mod(idx, val)) % MOD2;
        idx++;
        if (len_arr[val] == len_arr[block_limit]) {
            if (val == block_limit) {
                ans = (ans + compute_segment(val * 10, idx, n)) % MOD2;
                idx = NTH_VAL;
                break;
            }
            ll tmp = val;
            for (int l = 1; l < MAX_S; ++l) {
                tmp *= 10;
                ll offset = diff_mod(idx - 1, tmp);
                auto it = lower_bound(seq[l].begin(), seq[l].end(), MOD1 - offset);
                int cnt = seq[l].end() - it;
                ans = (ans + prefix[l] + 1LL * cnt * MOD1 % MOD2) % MOD2;
                ans = (ans + offset * (ll)seq[l].size() % MOD2) % MOD2;
            }
            idx += PRE_SIZE;
        }
        val = next_val(val, block_limit);
    }

    ll max_val = 1;
    for (int i = 0; i < len_arr[block_limit] + 6; ++i) max_val *= 10;
    max_val--;
    block_limit = max_val / 1000000;

    val /= 10;
    val++;
    while (val % 10 == 0) val /= 10;

    while (val != 1) {
        ans = (ans + diff_mod(idx, val)) % MOD2;
        idx++;
        if (len_arr[val] == len_arr[block_limit]) {
            ll tmp = val;
            for (int l = 1; l < MAX_S; ++l) {
                tmp *= 10;
                ll offset = diff_mod(idx - 1, tmp);
                auto it = lower_bound(seq[l].begin(), seq[l].end(), MOD1 - offset);
                int cnt = seq[l].end() - it;
                ans = (ans + prefix[l] + 1LL * cnt * MOD1 % MOD2) % MOD2;
                ans = (ans + offset * (ll)seq[l].size() % MOD2) % MOD2;
            }
            idx += PRE_SIZE;
        }
        val = next_val(val, block_limit);
    }

    cout << ans << '\n';
    return 0;
}
